args.sparql:
SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Blood_and_Black_Lace dbr:The_Fighting_Fool }
  ?film (dbo:director|dbp:director) ?director .
  OPTIONAL { ?director dbo:birthDate ?birthDate }
  OPTIONAL { ?director dbp:birth_date ?birthDate }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER (lang(?directorLabel) = "en") }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER (lang(?filmLabel) = "en") }
}

SELECT DISTINCT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Blood_and_Black_Lace dbr:The_Fighting_Fool }
  ?film (dbo:director|dbp:director) ?director .
  OPTIONAL { ?director dbo:birthDate ?bd1 }
  OPTIONAL { ?director dbp:birth_date ?bd2 }
  BIND(coalesce(?bd1, ?bd2) AS ?birthDate)
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }
} ORDER BY ?film

SELECT DISTINCT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Blood_and_Black_Lace dbr:The_Fighting_Fool }
  ?film (dbo:director|dbp:director) ?director .
  OPTIONAL { ?director dbo:birthDate ?bd1 }
  OPTIONAL { ?director dbp:birth_date ?bd2 }
  BIND(coalesce(?bd1, ?bd2) AS ?birthDate)
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }
} ORDER BY ?film

